import { MeshStandardNodeMaterial, MeshPhysicalNodeMaterial } from 'three/webgpu';
import { uv, mix, color, vec2, length, max, sub, step, smoothstep } from 'three/tsl';
import { gsap } from 'gsap';
import { } from '@/primitives';
import { } from '@/text';

export default function createNode(config, ctx) {
  const { Group, Mesh, PlaneGeometry, CylinderGeometry, Color } = ctx.THREE;

  // Root container
  const root = new Group();
  root.name = 'feature-triptych-root';

  // ------------------------------------------------------------------
  // Backdrop gradient plane (stage)
  // ------------------------------------------------------------------
  const backdropGeom = new PlaneGeometry(7, 6);
  const backdropMat = new MeshStandardNodeMaterial();
  // vertical gradient from #191921 to #121218
  const gradColor = mix(
    color(0x191921),
    color(0x121218),
    uv().y
  );
  backdropMat.colorNode = gradColor;
  backdropMat.metalness = 0;
  backdropMat.roughness = 1;
  backdropMat.transparent = false;

  const backdropMesh = new Mesh(backdropGeom, backdropMat);
  backdropMesh.position.z = -2.5;
  root.add(backdropMesh);

  // ------------------------------------------------------------------
  // Card layout constants
  // ------------------------------------------------------------------
  const CARD_W = 1.5;
  const CARD_H = 1.9;
  const GAP = 0.25; // base unit spacing
  const ROW_TOTAL_W = 5.0; // as spec
  const START_X = -ROW_TOTAL_W / 2 + CARD_W / 2; // -1.75
  const CARD_POS_X = [START_X, 0, -START_X]; // -1.75, 0, +1.75

  // Text style defaults
  const TEXT_COLOR = '#e8ecf2';
  const GLYPH_COLOR = '#ff2a38';
  const BORDER_COLOR = '#26262f';
  const BORDER_WIDTH = 0.006;

  // Store cleanup resources
  const disposables = [];

  // ------------------------------------------------------------------
  // Create each card
  // ------------------------------------------------------------------
  const cardData = [
    {
      glyph: '01',
      title: 'In-House Calibre',
      body: 'Every movement is designed, machined, and finished under one roof.'
    },
    {
      glyph: '02',
      title: 'Five-Year Guarantee',
      body: 'Each piece is serviced free of charge for five years from delivery.'
    },
    {
      glyph: '03',
      title: 'Hand-Finished Dials',
      body: 'Guilloche cut on a 1912 rose engine, one dial at a time.'
    }
  ];

  const allTimelines = [];

  cardData.forEach((item, idx) => {
    const cardGroup = new Group();
    cardGroup.name = `card-${idx + 1}`;
    cardGroup.position.set(CARD_POS_X[idx], 0, 0);
    root.add(cardGroup);

    // ------------------------------
    // Card background plane
    // ------------------------------
    const cardGeom = new PlaneGeometry(CARD_W, CARD_H);
    const cardMat = new MeshStandardNodeMaterial();
    // vertical gradient albedo
    const albedoNode = mix(
      color(0x191921),
      color(0x121218),
      uv().y
    );
    // add border via simple step on uv
    const borderMask = max(
      step(BORDER_WIDTH, uv().x),
      step(BORDER_WIDTH, uv().y)
    );
    const borderMaskInv = sub(1, borderMask);
    const finalColor = mix(
      albedoNode,
      color(0x26262f),
      borderMaskInv
    );
    cardMat.colorNode = finalColor;
    cardMat.metalness = 0.25;
    cardMat.roughness = 0.6;
    cardMat.clearcoat = 0.15;
    cardMat.transparent = true;
    const cardMesh = new Mesh(cardGeom, cardMat);
    cardGroup.add(cardMesh);
    disposables.push(cardGeom, cardMat);

    // ------------------------------
    // Contact shadow (simple dark plane)
    // ------------------------------
    const shadowGeom = new PlaneGeometry(CARD_W, CARD_H);
    const shadowMat = new MeshStandardNodeMaterial();
    shadowMat.colorNode = color(0x000000);
    shadowMat.opacityNode = step(0, 0); // start fully transparent
    shadowMat.transparent = true;
    const shadowMesh = new Mesh(shadowGeom, shadowMat);
    shadowMesh.position.z = -0.01;
    cardGroup.add(shadowMesh);
    disposables.push(shadowGeom, shadowMat);

    // ------------------------------
    // Icon seat (machined disc)
    // ------------------------------
    const discRadius = 0.2; // diameter 0.4
    const discHeight = 0.05;
    const discGeom = new CylinderGeometry(discRadius, discRadius, discHeight, 32);
    const discMat = new MeshStandardNodeMaterial();
    discMat.metalness = 0.5;
    discMat.roughness = 0.55;
    discMat.clearcoat = 0.2;
    discMat.anisotropy = 0.6; // note: node material property may not exist; ignored if unsupported
    const discMesh = new Mesh(discGeom, discMat);
    // position disc near top edge with padding
    const PAD = 0.375;
    const iconCenterY = CARD_H / 2 - PAD - discRadius;
    discMesh.position.set(0, iconCenterY, 0);
    cardGroup.add(discMesh);
    disposables.push(discGeom, discMat);

    // ------------------------------
    // Glyph text (emissive)
    // ------------------------------
    const glyphObj = ctx.fontAtlas.createText(item.glyph, {
      fontSize: 20,
      color: GLYPH_COLOR,
      align: 'center'
    });
    glyphObj.name = 'glyph';
    glyphObj.position.set(0, iconCenterY, discHeight / 2 + 0.001);
    cardGroup.add(glyphObj);

    // ------------------------------
    // Title text
    // ------------------------------
    const titleObj = ctx.fontAtlas.createText(item.title, {
      fontSize: 20,
      color: TEXT_COLOR,
      align: 'center'
    });
    titleObj.name = 'title';
    const TITLE_GAP = 0.25;
    const titleY = iconCenterY - discRadius - TITLE_GAP - 0.1; // approximate offset
    titleObj.position.set(0, titleY, 0.001);
    cardGroup.add(titleObj);

    // ------------------------------
    // Body text
    // ------------------------------
    const bodyObj = ctx.fontAtlas.createText(item.body, {
      fontSize: 13,
      color: TEXT_COLOR,
      align: 'center',
      lineHeight: 1.5,
      maxWidthPx: 300
    });
    bodyObj.name = 'body';
    const BODY_GAP = 0.125;
    const bodyY = titleY - 0.12 - BODY_GAP; // rough estimate
    bodyObj.position.set(0, bodyY, 0.001);
    cardGroup.add(bodyObj);

    // ------------------------------
    // Hover interaction (lift + shadow + emissive boost)
    // ------------------------------
    const hoverTimeline = gsap.timeline({ paused: true });
    hoverTimeline.to(cardGroup.position, {
      y: 0.06,
      z: 0.12,
      duration: 0.18,
      ease: 'cubic-bezier(0.25,0.46,0.45,0.94)'
    }, 0);
    hoverTimeline.to(shadowMesh.scale, {
      x: 1.2,
      y: 1.2,
      duration: 0.18,
      ease: 'cubic-bezier(0.25,0.46,0.45,0.94)'
    }, 0);
    hoverTimeline.to(shadowMat, {
      opacityNode: 0.3,
      duration: 0.18,
      ease: 'cubic-bezier(0.25,0.46,0.45,0.94)'
    }, 0);
    // emissive intensity boost (if material supports)
    let glyphMaterial = null;
    glyphObj.traverse((c) => {
      if (c.isMesh && c.material && 'emissiveIntensity' in c.material) {
        glyphMaterial = c.material;
      }
    });
    if (glyphMaterial) {
      hoverTimeline.to(glyphMaterial, {
        emissiveIntensity: 2.2,
        duration: 0.18,
        ease: 'cubic-bezier(0.25,0.46,0.45,0.94)'
      }, 0);
    }

    // Store handlers
    cardGroup.userData.handlers = {
      hoverEnter: () => hoverTimeline.play(),
      hoverLeave: () => hoverTimeline.reverse()
    };
    allTimelines.push(hoverTimeline);
  });

  // ------------------------------------------------------------------
  // Stagger entrance animation for the three cards
  // ------------------------------------------------------------------
  const entranceTimeline = gsap.timeline();
  root.children
    .filter((c) => c.name.startsWith('card-'))
    .forEach((cardGroup, i) => {
      const delay = i * 0.08;
      const startY = cardGroup.position.y + 0.2;
      const startOpacity = 0;
      // initial state
      cardGroup.position.y = startY;
      cardGroup.traverse((obj) => {
        if (obj.material && 'opacity' in obj.material) {
          obj.material.transparent = true;
          obj.material.opacity = startOpacity;
        }
      });
      entranceTimeline.to(cardGroup.position, {
        y: 0,
        duration: 0.5,
        ease: 'cubic-bezier(0.25,0.46,0.45,0.94)',
        delay
      }, 0);
      entranceTimeline.to(cardGroup, {
        // dummy target to animate opacity of children
        onUpdate: () => {
          cardGroup.traverse((obj) => {
            if (obj.material && 'opacity' in obj.material) {
              obj.material.opacity = 1 - (obj.position.y - 0) / 0.2;
            }
          });
        },
        duration: 0.5,
        delay
      }, 0);
    });
  allTimelines.push(entranceTimeline);

  // ------------------------------------------------------------------
  // Load optional image texture (if provided) and apply to card backs
  // ------------------------------------------------------------------
  if (config.imageUrl) {
    ctx.textureLoader.loadTexture(config.imageUrl).then((tex) => {
      root.children.forEach((c) => {
        if (c.name.startsWith('card-') && c.children[0] && c.children[0].material) {
          c.children[0].material.map = tex;
          c.children[0].material.needsUpdate = true;
        }
      });
    });
  }

  // ------------------------------------------------------------------
  // Cleanup
  // ------------------------------------------------------------------
  root.userData.cleanup = () => {
    allTimelines.forEach((t) => t.kill());
    disposables.forEach((d) => {
      if (d.isTexture) d.dispose();
      else if (d.isMaterial) d.dispose();
      else if (d.isGeometry) d.dispose();
    });
    // dispose any loaded texture if we kept reference (not required as loaders cache)
    if (root.parent) root.parent.remove(root);
  };

  return root;
}
